      }
    },
    {
      "card_id": "cell-detect",
      "instruction": "Equilibrate plates, add CellTiter-Glo reagent 1:1, mix, stabilize, and read luminescence.",
      "parameters": {
        "reagent_volume": "assumption: equal to culture volume per well (1:1 reagent:medium), per manufacturer-style procedure; not packet-sourced",
        "mix_time": "assumption: 2 min orbital shaking; unresolved from packet",
        "stabilization_time": "assumption: 10 min at room temperature; unresolved from packet"
      }
    },
    {
      "card_id": "analyse",
      "instruction": "Subtract background (medium + reagent, no cells), normalize each well to the mean vehicle control, fit a 4-parameter logistic concentration-response curve, and report IC50/EC50 with confidence intervals.",
      "parameters": {
        "fit_model": "4-parameter logistic (variable slope), log10 concentration",
        "acceptance_criteria": "assumption: vehicle wells within ±20% of plate-mean vehicle; background <5% of vehicle signal; Z'-like separation between vehicle and a positive reference control; no packet-sourced criteria"
